from collections import deque


class Solution:
    def highestPeak(self, isWater: list[list[int]]) -> list[list[int]]:
        m, n = len(isWater), len(isWater[0])
        height = [[-1] * n for _ in range(m)]   # -1 = not assigned yet
        queue = deque()
        for r in range(m):
            for c in range(n):
                if isWater[r][c]:
                    height[r][c] = 0
                    queue.append((r, c))          # every water cell is a source
        while queue:                              # each cell enqueued once: O(m * n)
            r, c = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < m and 0 <= nc < n and height[nr][nc] == -1:
                    height[nr][nc] = height[r][c] + 1   # distance to nearest water = max height
                    queue.append((nr, nc))
        return height
